// Single data access layer. Components must import data from here only.
// To switch to real model output / a FastAPI endpoint later, change only this file:
// keep the function names and return shapes, replace the bodies with fetch() calls.
//
// The mock JSON is generated by scripts/generate-mock.mjs (all numbers are FAKE).

import districtsRaw from './districts.geojson?raw';
import forecast from './risk_forecast.json';
import replay from './replay_2025.json';
import actions from './actions.json';
import drivers from './drivers.json';
import portfolio from './partner_portfolio.json';

const districts = JSON.parse(districtsRaw);

/** GeoJSON FeatureCollection; properties: district_id, name_en, name_km, province_en, province_km */
export async function getDistricts() {
  return districts;
}

/** { generated_at, districts: [{ district_id, risk_level, probability, drivers[], forecast[], action_id }] } */
export async function getForecast() {
  return forecast;
}

/** [{ date, district_id, risk_level, probability, observed_flood }] sorted by date */
export async function getReplay() {
  return replay;
}

/** [{ id, en, km }] fixed list of farmer actions */
export async function getActions() {
  return actions;
}

/** [{ id, source, en, km }] explanation for each driver id */
export async function getDrivers() {
  return drivers;
}

/** [{ district_id, clients, value_usd }] */
export async function getPortfolio() {
  return portfolio;
}
